-- Run once in Supabase SQL Editor (opportunity-automation project).
--
-- Adds social-media detection + need-based tailoring columns, and
-- restructures settings so locations and business categories are
-- independent lists (every category searched in every location).
-- If you already ran an earlier version of this file, this is safe
-- to re-run: ALTERs use IF NOT EXISTS, and the settings UPDATE at the
-- bottom overwrites the old structure with the new one.

alter table leads add column if not exists notion_page_id text;
alter table leads add column if not exists gmail_thread_id text;
alter table leads add column if not exists has_social boolean;
alter table leads add column if not exists need_type text; -- 'website' | 'social' | 'both'

create table if not exists settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

alter table settings enable row level security;
drop policy if exists "anon can read settings" on settings;
drop policy if exists "anon can update settings" on settings;
create policy "anon can read settings" on settings for select using (true);
create policy "anon can update settings" on settings for update using (true) with check (true);

insert into settings (key, value) values
  ('places_queries', '{"max_new_leads_per_run": 5, "_comment": "locations x categories = every combo gets searched. Add a location and it applies to every category automatically, and vice versa.", "locations": [{"name": "State College, PA", "lat": 40.7982, "lng": -77.8599, "radius_meters": 12000}], "categories": [{"search_term": "restaurants", "category": "restaurant"}, {"search_term": "cafes and coffee shops", "category": "cafe"}, {"search_term": "hair salons", "category": "salon"}, {"search_term": "spas and nail salons", "category": "spa"}, {"search_term": "gyms and fitness studios", "category": "fitness"}, {"search_term": "yoga studios", "category": "fitness"}, {"search_term": "general contractors", "category": "contractor"}, {"search_term": "electricians", "category": "contractor"}, {"search_term": "plumbers", "category": "contractor"}, {"search_term": "HVAC companies", "category": "contractor"}, {"search_term": "landscaping companies", "category": "contractor"}, {"search_term": "bars", "category": "bar"}, {"search_term": "real estate agents", "category": "real-estate"}, {"search_term": "law firms", "category": "legal"}, {"search_term": "accountants and CPAs", "category": "financial"}, {"search_term": "insurance agents", "category": "financial"}, {"search_term": "dentists", "category": "medical"}, {"search_term": "chiropractors", "category": "medical"}, {"search_term": "physical therapy clinics", "category": "medical"}, {"search_term": "veterinarians", "category": "medical"}, {"search_term": "auto repair shops", "category": "automotive"}, {"search_term": "photographers", "category": "creative"}, {"search_term": "event venues", "category": "events"}, {"search_term": "florists", "category": "retail"}, {"search_term": "bakeries", "category": "retail"}, {"search_term": "boutique clothing stores", "category": "retail"}, {"search_term": "tutoring services", "category": "education"}, {"search_term": "daycare and childcare centers", "category": "childcare"}, {"search_term": "pet groomers", "category": "pet-services"}, {"search_term": "cleaning services", "category": "home-services"}]}'::jsonb),
  ('outreach', '{"reply_to_email": "YOUR_EMAIL@example.com", "max_sends_per_run": 25, "test_mode": true, "test_recipient_email": "YOUR_EMAIL@example.com", "sender_name": "YOUR_NAME", "touch_sets": {"website": [{"step": 1, "delay_days": 0, "subject": "Quick note about {business_name}''s website", "body": "Hi there,\n\nI noticed {business_name}''s website {issue_line}. I put together a quick look at what it could look like fixed \u2014 attached below.\n\nI run a small studio here in State College helping local businesses with website builds and ongoing social media management. If a refresh would help, happy to send over a couple options. No pressure either way.\n\nBest,\n{sender_name}"}], "social": [{"step": 1, "delay_days": 0, "subject": "Quick note about {business_name}''s social media", "body": "Hi there,\n\nI noticed {business_name} {issue_line} \u2014 your website looks solid, so this is really just about visibility. I help local businesses with ongoing social media management: consistent posting, real engagement, no extra work on your end.\n\nIf that''d be useful, happy to send over what that could look like for {business_name}. No pressure either way.\n\nBest,\n{sender_name}"}], "both": [{"step": 1, "delay_days": 0, "subject": "Quick note about {business_name}''s website & socials", "body": "Hi there,\n\nI noticed {business_name} {issue_line}. I put together a quick look at what a refreshed site could look like \u2014 attached below \u2014 and I also do ongoing social media management for local businesses.\n\nHappy to help with one or both, whatever''s actually useful. No pressure either way.\n\nBest,\n{sender_name}"}]}, "followups": [{"step": 2, "delay_days": 7, "subject": "Following up \u2014 {business_name}", "body": "Hi again,\n\nJust following up on my note about {offer_phrase} for {business_name}. Totally understand if it''s not a priority right now \u2014 if it ever is, I''m here.\n\nBest,\n{sender_name}"}, {"step": 3, "delay_days": 7, "subject": "Checking in \u2014 {business_name}", "body": "Hi,\n\nStill happy to help with {offer_phrase} whenever the timing''s right. No obligation, just wanted to stay on your radar.\n\nBest,\n{sender_name}"}, {"step": 4, "delay_days": 7, "subject": "One more thought \u2014 {business_name}", "body": "Hi,\n\nA lot of the local businesses I work with start small \u2014 even just a first step on {offer_phrase} can make a real difference. Happy to talk through what that could look like for {business_name}.\n\nBest,\n{sender_name}"}, {"step": 5, "delay_days": 7, "subject": "Still around \u2014 {business_name}", "body": "Hi,\n\nJust another friendly check-in on {offer_phrase}. If it becomes useful down the line, I''m easy to reach.\n\nBest,\n{sender_name}"}, {"step": 6, "delay_days": 7, "subject": "Last note \u2014 {business_name}", "body": "Hi one more time,\n\nI''ll leave this as my last check-in for now on {offer_phrase}. If it''s ever useful, feel free to reach out any time \u2014 no expiration on the offer.\n\nBest,\n{sender_name}"}]}'::jsonb),
  ('digest', '{"to_email": "YOUR_EMAIL@example.com", "from_email": "onboarding@resend.dev", "subject_prefix": "Raw Leads \u2014", "only_todays_captures": true}'::jsonb)
on conflict (key) do update set value = excluded.value, updated_at = now();
